import landPoints from './usLandCellPoints.json';
import rows from './usLandCells.json';
import type { SweepCell } from './meetingSweep';

/**
 * Base cells for the Meeting Guide sweep: all US land, including Alaska, Hawaii and
 * the territories, and no open water, Canada or Mexico. Generated by
 * scripts/generateUsLandCells.mjs. Rows are "south|latStep|lngStep|west:count,...".
 *
 * A cell centered on water is listed twice, once with a land search point
 * ("south|west|lat|lng"), because the API answers only for organizations whose service
 * area holds the search point. Its center is still searched too, in case that finds an
 * island the land point's organization doesn't serve.
 */
export function usBaseCells(): SweepCell[] {
  const cells: SweepCell[] = [];
  const byCorner = new Map<string, SweepCell>();
  for (const row of rows as string[]) {
    const [south, latStep, lngStep, runs] = row.split('|');
    const s = Number(south);
    const n = s + Number(latStep);
    const width = Number(lngStep);
    for (const run of runs.split(',')) {
      const [west, count] = run.split(':').map(Number);
      for (let i = 0; i < count; i++) {
        const cell = { s, n, w: west + i * width, e: west + (i + 1) * width };
        cells.push(cell);
        byCorner.set(`${cell.s}|${cell.w}`, cell);
      }
    }
  }
  for (const row of landPoints as string[]) {
    const [south, west, lat, lng] = row.split('|');
    const cell = byCorner.get(`${Number(south)}|${Number(west)}`);
    if (cell) cells.push({ ...cell, point: { lat: Number(lat), lng: Number(lng) } });
  }
  return cells;
}
